{
  "packet_id": "H6-T04-3",
  "claim_id": "C050",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C050.component",
    "value": "Missing offline activity constrains conclusions.",
    "scope": "The inferential limitation from unobserved offline activity, distinct from the factual statement that existing events omit preparation.",
    "provenance": {
      "refs": [
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P030 explicitly identifies missing offline activity as a constraint on conclusions."
    }
  },
  "signal_basis": {
    "component_id": "C050.signal_basis",
    "value": "Account-level event sequences are inspected and consenting customers across event paths are asked about offline preparation, which existing events omit.",
    "scope": "Comparisons involve accounts of similar age and checks of event completeness; customer inquiry includes publishers and non-publishers. The limitation concerns offline activity that remains unobserved.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P006",
          "role": "SUPPORT"
        },
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P030",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans establish the omitted activity, the evidence-gathering operations and the resulting limitation."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C050.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported limitation."
    }
  },
  "rationale": "Unobserved preparation can affect how recorded progress or inactivity should be interpreted. Even when discriminating patterns occur, missing offline activity limits the conclusions those observations license. The claim asserts this bounded limitation without asserting a particular hidden cause.",
  "uncertainty": "The packet does not quantify how much offline activity remains missing or how strongly it affects particular conclusions; neither is required by this claim.",
  "anomalies": []
}
